// Esperar a que carguen los datos
cy.get("body", {
  timeout: 10000
}).should("contain.text", "Total de Usuarios");
// Total de usuarios
cy.contains("Total de Usuarios").should("exist");
// Administradores
cy.contains("Administradores").should("exist");
// Responsables
// Se usa exist porque Cypress detecta que este elemento
// puede estar recortado por el overflow de su contenedor.
cy.contains("Responsables").should("exist");
// Operativos
cy.contains("Operativos").should("exist");
// Estadísticas
cy.contains("Usuarios registrados").should("exist");
cy.contains("Control del sistema y configuraciones").should("exist");
cy.contains("Responsables de activos").should("exist");
cy.contains("Gestor de Tickets y técnicos de mantenimiento").should("exist");

cy.contains("button", "Todos").should("be.visible");
cy.contains("button", "Administradores").should("be.visible");
cy.contains("button", "Responsables").should("be.visible");
cy.contains("button", "Gestor de Tickets").should("be.visible");
cy.contains("button", "Técnicos de mantenimiento").should("be.visible");

// Administradores
cy.contains("button", "Administradores").click();
cy.contains("button", "Administradores").should("have.class", "active");
// Responsables
cy.contains("button", "Responsables").click();
cy.contains("button", "Responsables").should("have.class", "active");
// Gestor de Tickets
cy.contains("button", "Gestor de Tickets").click();
cy.contains("button", "Gestor de Tickets").should("have.class", "active");
// Técnicos de mantenimiento
cy.contains("button", "Técnicos de mantenimiento").click();
cy.contains("button", "Técnicos de mantenimiento").should("have.class", "active");
// Volver a Todos
cy.contains("button", "Todos").click();
cy.contains("button", "Todos").should("have.class", "active");
